import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../auth/AuthContext';

const Profile = () => {
  const { user, logout, bookedTickets } = useAuth();
  const navigate = useNavigate();
  
  const [editMode, setEditMode] = useState(false);
  const [loading, setLoading] = useState(false);
  
  // Real data only - from signup + user input
  const [profile, setProfile] = useState({
    fullName: user?.fullName || '',
    email: user?.email || '',
    devoteeId: `TC${Date.now().toString().slice(-6)}`,
    mobile: '',
    dob: '',
    gender: '',
    idProofType: '',
    idProofNumber: '',
    city: '',
    pincode: ''
  });

  // Load saved profile data on mount
  useEffect(() => {
    const saved = localStorage.getItem('templeProfile');
    if (saved) {
      setProfile(JSON.parse(saved));
    }
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setProfile(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSaveProfile = async () => {
    if (!profile.mobile || !profile.dob || !profile.idProofNumber || !profile.city || !profile.pincode) {
      alert('Please fill all required fields (*)');
      return;
    }

    setLoading(true);
    try {
      // Save to localStorage (persistent)
      localStorage.setItem('templeProfile', JSON.stringify(profile));
      
      // Update user in AuthContext
      const updatedUser = { ...user, fullName: profile.fullName };
      localStorage.setItem('user', JSON.stringify(updatedUser));
      
      alert('✅ Profile saved successfully! 🙏');
      setEditMode(false);
    } catch (error) {
      alert('Save failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-temple-beige to-white">
      {/* Profile Header */}
      <div className="bg-gradient-to-r from-emerald-500 to-teal-600 text-white py-20 relative overflow-hidden">
        <div className="absolute inset-0 bg-black/20" />
        <div className="relative max-w-6xl mx-auto px-4 text-center">
          <div className="inline-flex items-center bg-white/20 backdrop-blur-sm rounded-full p-2 mb-6">
            <div className="w-24 h-24 bg-gradient-to-br from-white/20 to-transparent rounded-full flex items-center justify-center backdrop-blur-sm shadow-2xl">
              <span className="text-5xl">👤</span>
            </div>
          </div>
          <h1 className="text-5xl md:text-6xl font-bold mb-4 drop-shadow-2xl">
            {profile.fullName || 'Complete Profile'}
          </h1>
          <div className="flex flex-col sm:flex-row gap-4 justify-center items-center text-2xl opacity-90 mb-4">
            <span>ID: <strong className="font-mono bg-white/20 px-4 py-2 rounded-2xl">{profile.devoteeId}</strong></span>
            {profile.mobile && (
              <span className="flex items-center bg-green-500/20 px-4 py-2 rounded-2xl backdrop-blur-sm">
                ✔ Profile Complete
              </span>
            )}
          </div>
          <p className="text-xl opacity-90">{profile.email}</p>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 py-12">
        <div className="grid lg:grid-cols-3 gap-8">
          
          {/* Left Sidebar */}
          <div className="lg:col-span-1 space-y-6">
            {/* Stats */}
            <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="bg-white/80 backdrop-blur-sm p-6 rounded-3xl shadow-xl text-center border border-gray-100">
                <div className="text-3xl font-bold text-emerald-600">{bookedTickets.length}</div>
                <div className="text-sm text-gray-600 mt-1">Bookings</div>
              </div>
              <div className="bg-white/80 backdrop-blur-sm p-6 rounded-3xl shadow-xl text-center border border-gray-100">
                <div className="text-3xl font-bold text-gray-500">
                  {profile.mobile ? 'Complete' : 'Incomplete'}
                </div>
                <div className="text-sm text-gray-600 mt-1">Profile</div>
              </div>
            </div>

            {/* Quick Actions */}
            <div className="bg-white/90 backdrop-blur-sm rounded-3xl shadow-2xl p-6 border border-gray-100">
              <h3 className="text-xl font-bold text-gray-900 mb-6">Quick Actions</h3>
              <div className="space-y-3">
                <Link to="/temples" className="w-full block p-4 bg-gradient-to-r from-emerald-500 to-teal-600 text-white rounded-2xl hover:shadow-xl transition-all text-center font-semibold">
                  Book Darshan →
                </Link>
                <Link to="/my-tokens" className="w-full flex items-center p-4 bg-gray-50 hover:bg-gray-100 rounded-2xl transition-all">
                  <span className="w-10 h-10 bg-blue-100 rounded-xl flex items-center justify-center mr-4">🎫</span>
                  My Tickets
                </Link>
              </div>
            </div>

            {/* Logout */}
            <button
              onClick={handleLogout}
              className="w-full bg-gradient-to-r from-red-500 to-red-600 hover:from-red-600 text-white font-bold py-4 px-6 rounded-3xl shadow-2xl hover:shadow-3xl transition-all duration-300 flex items-center justify-center space-x-2"
            >
              <span>🚪</span>
              <span>Logout</span>
            </button>
          </div>

          {/* Main Content - Editable Profile Form */}
          <div className="lg:col-span-2">
            <div className="bg-white/90 backdrop-blur-sm rounded-3xl p-8 shadow-2xl border border-gray-100">
              {/* Edit Toggle */}
              <div className="flex justify-between items-center mb-8">
                <h2 className="text-3xl font-bold text-gray-900 flex items-center">
                  <span className="w-12 h-12 bg-gradient-to-r from-blue-500 to-indigo-500 rounded-2xl flex items-center justify-center text-2xl mr-4 text-white shadow-lg">👤</span>
                  Profile Details
                </h2>
                <button
                  onClick={() => setEditMode(!editMode)}
                  disabled={loading}
                  className={`px-8 py-3 font-semibold rounded-2xl shadow-xl transition-all duration-300 flex items-center space-x-2 ${
                    editMode
                      ? 'bg-gradient-to-r from-emerald-500 to-teal-600 text-white hover:shadow-3xl'
                      : 'bg-gradient-to-r from-temple-gold to-amber-600 text-white hover:shadow-2xl'
                  } disabled:opacity-50`}
                >
                  {editMode ? (
                    <>
                      <span>💾</span>
                      <span>{loading ? 'Saving...' : 'Save Profile'}</span>
                    </>
                  ) : (
                    <>
                      <span>✏️</span>
                      <span>Edit Profile</span>
                    </>
                  )}
                </button>
              </div>

              {/* Form Fields */}
              <div className="grid md:grid-cols-2 gap-6">
                {/* Full Name */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Full Name <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    name="fullName"
                    value={profile.fullName}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  />
                </div>

                {/* Mobile * */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Mobile Number <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="tel"
                    name="mobile"
                    value={profile.mobile}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    placeholder="+91 9876543210"
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  />
                </div>

                {/* DOB * */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Date of Birth <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="date"
                    name="dob"
                    value={profile.dob}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    max="2005-01-01"
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  />
                </div>

                {/* Gender */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Gender</label>
                  <select
                    name="gender"
                    value={profile.gender}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  >
                    <option value="">Select Gender</option>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Other">Other</option>
                  </select>
                </div>

                {/* ID Proof Type * */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    ID Proof <span className="text-red-500">*</span>
                  </label>
                  <select
                    name="idProofType"
                    value={profile.idProofType}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  >
                    <option value="">Select ID</option>
                    <option value="Aadhaar">Aadhaar (Last 4 digits)</option>
                    <option value="VoterID">Voter ID</option>
                    <option value="Passport">Passport</option>
                  </select>
                </div>

                {/* ID Number * */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    ID Number <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    name="idProofNumber"
                    value={profile.idProofNumber}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    placeholder="Last 4 digits only"
                    maxLength="16"
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  />
                </div>

                {/* City * */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    City <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    name="city"
                    value={profile.city}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  />
                </div>

                {/* Pincode * */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Pincode <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    name="pincode"
                    value={profile.pincode}
                    onChange={handleInputChange}
                    disabled={!editMode}
                    maxLength="6"
                    className={`w-full p-4 border-2 rounded-2xl focus:ring-2 focus:ring-temple-gold transition-all shadow-sm ${
                      editMode
                        ? 'border-gray-200 hover:border-gray-300'
                        : 'bg-gray-50 border-gray-200 cursor-not-allowed'
                    }`}
                  />
                </div>
              </div>

              {/* Required Notice */}
              <div className="mt-6 p-4 bg-yellow-50 border-2 border-yellow-200 rounded-2xl">
                <p className="text-sm text-yellow-800">
                  <span className="font-bold">* Required</span> fields are mandatory for booking Darshan tickets
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Profile;
